import { Chess } from 'https://cdn.jsdelivr.net/npm/chess.js@1.4.0/+esm';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const PIECES = {wk:'♔',wq:'♕',wr:'♖',wb:'♗',wn:'♘',wp:'♙',bk:'♚',bq:'♛',br:'♜',bb:'♝',bn:'♞',bp:'♟'};
const FILES = 'abcdefgh';
let game = new Chess();
let playerColor = 'w';
let boardFlipped = false;
let selectedSquare = null;
let legalTargets = [];
let lastMove = null;
let busy = false;
let difficulty = 2;
let gameOver = false;
let soundEnabled = false;
let toastTimer;
let puzzleIndex = 0;
let puzzleScore = 0;
let puzzleGame;
let puzzleSelected = null;
let puzzleTargets = [];
let puzzleSolved = false;
let puzzleHinted = false;
let analysisEntries = [];

// A fast local alpha-beta opponent. It evaluates material, central control, pawn structure,
// king exposure and piece activity; no position or move is sent off-device.
const VALUES = {p:100,n:315,b:330,r:500,q:900,k:20000};
function evaluate(position) {
  const board = position.board();
  let score = 0, phase = 0;
  for (let r=0;r<8;r++) for (let c=0;c<8;c++) {
    const p=board[r][c]; if (!p) continue;
    const sign=p.color==='w'?1:-1, advance=p.color==='w'?6-r:r-1;
    const center=7-(Math.abs(3.5-r)+Math.abs(3.5-c));
    let positional=0;
    if(p.type==='p') positional=advance*7+center*2;
    if(p.type==='n') positional=center*8;
    if(p.type==='b') positional=center*4;
    if(p.type==='r') positional=advance*1.5;
    if(p.type==='q') positional=center*2;
    if(p.type==='k') positional=phase<12? -center*5 : center*5;
    score+=sign*(VALUES[p.type]+positional);
    if(p.type!=='p'&&p.type!=='k') phase++;
  }
  // Small mobility bonus prevents the engine from hiding its pieces.
  const side=position.turn();
  let mobility=0;
  try { mobility=position.moves().length; } catch {}
  score+=(side==='w'?1:-1)*mobility*1.3;
  if(position.isCheck()) score+=(side==='w'?-1:1)*24;
  return score;
}
function orderedMoves(pos) {
  return pos.moves({verbose:true}).sort((a,b)=>{
    const score=m=> (m.captured?VALUES[m.captured]*10-VALUES[m.piece]:0)+(m.promotion?800:0)+(m.san.includes('+')?60:0)+(m.san.includes('#')?50000:0);
    return score(b)-score(a);
  });
}
function searchBest(pos, depth=2, nodeLimit=12000) {
  let nodes=0;
  const negamax=(d,alpha,beta,ply)=>{
    nodes++;
    if(pos.isCheckmate()) return -20000+ply;
    if(pos.isDraw()||pos.isStalemate()) return 0;
    if(d<=0||nodes>=nodeLimit) return (pos.turn()==='w'?1:-1)*evaluate(pos);
    let best=-Infinity;
    for(const move of orderedMoves(pos)) {
      pos.move({from:move.from,to:move.to,promotion:move.promotion});
      const val=-negamax(d-1,-beta,-alpha,ply+1);
      pos.undo();
      if(val>best) best=val;
