import { Chess } from 'https://cdn.jsdelivr.net/npm/chess.js@1.4.0/+esm';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const PIECES={wk:'♔',wq:'♕',wr:'♖',wb:'♗',wn:'♘',wp:'♙',bk:'♚',bq:'♛',br:'♜',bb:'♝',bn:'♞',bp:'♟'},FILES='abcdefgh';
let game=new Chess(),playerColor='w',boardFlipped=false,selectedSquare=null,legalTargets=[],lastMove=null,busy=false,difficulty=2,gameOver=false,soundEnabled=false,toastTimer;
let puzzleIndex=0,puzzleScore=0,puzzleGame,puzzleSelected=null,puzzleTargets=[],puzzleSolved=false;
const VALUES={p:100,n:315,b:330,r:500,q:900,k:20000};
function evaluate(pos){let score=0,phase=0;const board=pos.board();for(let r=0;r<8;r++)for(let c=0;c<8;c++){const p=board[r][c];if(!p)continue;const sign=p.color==='w'?1:-1,advance=p.color==='w'?6-r:r-1,center=7-(Math.abs(3.5-r)+Math.abs(3.5-c));let positional=0;if(p.type==='p')positional=advance*7+center*2;if(p.type==='n')positional=center*8;if(p.type==='b')positional=center*4;if(p.type==='r')positional=advance*1.5;if(p.type==='q')positional=center*2;if(p.type==='k')positional=phase<12?-center*5:center*5;score+=sign*(VALUES[p.type]+positional);if(p.type!=='p'&&p.type!=='k')phase++;}let mobility=0;try{mobility=pos.moves().length;}catch{}score+=(pos.turn()==='w'?1:-1)*mobility*1.3;if(pos.isCheck())score+=(pos.turn()==='w'?-1:1)*24;return score;}
function orderedMoves(pos){return pos.moves({verbose:true}).sort((a,b)=>{const s=m=>(m.captured?VALUES[m.captured]*10-VALUES[m.piece]:0)+(m.promotion?800:0)+(m.san.includes('+')?60:0)+(m.san.includes('#')?50000:0);return s(b)-s(a);});}
function searchBest(pos,depth=2,nodeLimit=12000){let nodes=0;const negamax=(d,alpha,beta,ply)=>{nodes++;if(pos.isCheckmate())return-20000+ply;if(pos.isDraw()||pos.isStalemate())return 0;if(d<=0||nodes>=nodeLimit)return(pos.turn()==='w'?1:-1)*evaluate(pos);let best=-Infinity;for(const m of orderedMoves(pos)){pos.move({from:m.from,to:m.to,promotion:m.promotion});const val=-negamax(d-1,-beta,-alpha,ply+1);pos.undo();if(val>best)best=val;if(val>alpha)alpha=val;if(alpha>=beta||nodes>=nodeLimit)break;}return best===-Infinity?0:best;};let bestMove=null,bestScore=-Infinity;for(const m of orderedMoves(pos)){pos.move({from:m.from,to:m.to,promotion:m.promotion});const score=-negamax(depth-1,-Infinity,Infinity,1);pos.undo();if(score>bestScore){bestScore=score;bestMove=m;}}return{move:bestMove,score:bestScore,nodes};}
function pieceMarkup(p){return p?`<span class="piece ${p.color==='w'?'white':'black'}">${PIECES[p.color+p.type]}</span>`:'';}
function renderBoard(el,pos,flipped,selected,targets,previous){if(!el)return;let html='';for(let row=0;row<8;row++){const rank=flipped?row+1:8-row;for(let col=0;col<8;col++){const file=flipped?7-col:col,sq=FILES[file]+rank,p=pos.get(sq),light=(file+rank)%2===0,classes=['square',light?'light':'dark'];if(selected===sq)classes.push('selected-square');if(previous?.from===sq)classes.push('last-from');if(previous?.to===sq)classes.push('last-to');if(targets.includes(sq))classes.push(p?'legal-capture':'legal-target');if(p?.type==='k'&&p.color===pos.turn()&&pos.isCheck())classes.push('check-square');html+=`<div class="${classes.join(' ')}" data-square="${sq}" role="gridcell" aria-label="${sq}${p?`, ${p.color==='w'?'white':'black'} ${p.type}`:''}">${pieceMarkup(p)}${col===0?`<span class="coord rank">${rank}</span>`:''}${row===7?`<span class="coord file">${FILES[file]}</span>`:''}</div>`;}}el.innerHTML=html;}
function updateBoard(){renderBoard($('#board'),game,boardFlipped,selectedSquare,legalTargets,lastMove);const history=game.history({verbose:true});$('#move-count').textContent=String(Math.ceil(history.length/2));$('#turn-indicator').textContent=gameOver?'GAME OVER':game.turn()===playerColor?'YOUR MOVE':'ENGINE THINKING';$('#last-move').textContent=history.length?`${history.at(-1).color==='w'?'White':'Black'} · ${history.at(-1).san}`:'The board is yours.';if(history.length){const m=history.at(-1),ev=evaluate(game)/100*(playerColor==='w'?1:-1);$('#analysis-note').innerHTML=`<span>◉</span> ${m.san}${m.san.includes('#')?' is checkmate.':m.san.includes('+')?' gives check.':m.color===playerColor?' — keep looking for forcing moves.':' — what changed in the position?'}`;$('#eval-score').textContent=`${ev>=0?'+':''}${ev.toFixed(1)}`;$('#eval-fill').style.width=`${Math.max(4,Math.min(96,50+ev*7))}%`;$('#eval-fill').style.background=ev>=0?'#88986e':'#d7d1c2';}else{$('#analysis-note').innerHTML='<span>◉</span> Make a move to see the position update.';$('#eval-score').textContent='+0.0';$('#eval-fill').style.width='50%';}renderMoveList();if(game.isGameOver())finishGame();}
function renderMoveList(){const h=game.history({verbose:true}),el=$('#move-list');if(!h.length){el.innerHTML='<div class="empty-moves">Your game will appear here.</div>';return;}let html='';for(let i=0;i<h.length;i+=2)html+=`<div class="move-row"><span class="move-num">${Math.floor(i/2)+1}.</span><span class="${i===h.length-1?'latest':''}">${h[i].san}</span><span class="${i+1===h.length-1?'latest':''}">${h[i+1]?.san||''}</span></div>`;el.innerHTML=html;el.scrollTop=el.scrollHeight;}
function finishGame(){if(gameOver)return;gameOver=true;const text=game.isCheckmate()?`${game.turn()==='w'?'Black':'White'} wins by checkmate.`:game.isStalemate()?'Draw by stalemate.':'Game drawn.';$('#analysis-note').innerHTML=`<span>◉</span> ${text}`;$('#turn-indicator').textContent='GAME OVER';showToast(text);}
function playMove(from,to,promotion='q'){if(busy||gameOver)return false;const m=game.move({from,to,promotion});if(!m)return false;lastMove={from:m.from,to:m.to};selectedSquare=null;legalTargets=[];updateBoard();playSound();if(!gameOver&&game.turn()!==playerColor){busy=true;setTimeout(engineMove,120);}return true;}
function onBoardClick(e){const cell=e.target.closest('[data-square]');if(!cell||busy||gameOver)return;const sq=cell.dataset.square,p=game.get(sq);if(selectedSquare&&legalTargets.includes(sq)){const moving=game.get(selectedSquare);if(moving?.type==='p'&&(sq[1]==='8'||sq[1]==='1')){showPromotion(selectedSquare,sq);return;}playMove(selectedSquare,sq);return;}if(p&&p.color===game.turn()&&p.color===playerColor){selectedSquare=sq;legalTargets=game.moves({square:sq,verbose:true}).map(m=>m.to);}else{selectedSquare=null;legalTargets=[];}updateBoard();}
function showPromotion(from,to){const dialog=$('#promotion-dialog'),opts=$('#promotion-options');opts.innerHTML=['q','r','b','n'].map(t=>`<button class="promotion-choice" data-piece="${t}" aria-label="Promote to ${t}">${PIECES[playerColor+t]}</button>`).join('');dialog.classList.remove('hidden');opts.onclick=e=>{const b=e.target.closest('[data-piece]');if(!b)return;dialog.classList.add('hidden');playMove(from,to,b.dataset.piece);};}
function engineMove(){if(game.isGameOver()){busy=false;finishGame();return;}difficulty=Number($('#difficulty').value);const depth=difficulty===1?1:difficulty===2?2:3,result=searchBest(game,depth,difficulty===3?22000:12000);if(result.move){const m=game.move({from:result.move.from,to:result.move.to,promotion:result.move.promotion||'q'});lastMove={from:m.from,to:m.to};playSound();}busy=false;updateBoard();}
function resetGame(){game=new Chess();selectedSquare=null;legalTargets=[];lastMove=null;busy=false;gameOver=false;playerColor=$('.color-option.selected').dataset.color;boardFlipped=playerColor==='b';$('#engine-level-label').textContent=['','Learning','Club player','Strong'][Number($('#difficulty').value)];$('.you-strip .player-id small').textContent=`Playing as ${playerColor==='w'?'White':'Black'}`;clocks={w:600,b:600};updateBoard();updateClocks();if(playerColor==='b'){busy=true;setTimeout(engineMove,250);}}
function undoMove(){if(busy)return;if(game.history().length){game.undo();if(game.turn()!==playerColor&&game.history().length)game.undo();gameOver=false;selectedSquare=null;legalTargets=[];const h=game.history({verbose:true});lastMove=h.length?{from:h.at(-1).from,to:h.at(-1).to}:null;updateBoard();}}
function hintMove(){if(busy||gameOver||game.turn()!==playerColor){showToast('Wait for your turn to ask for a hint.');return;}const r=searchBest(game,2,9000);if(!r.move){showToast('No legal moves.');return;}selectedSquare=r.move.from;legalTargets=[r.move.to];updateBoard();showToast(`Try ${r.move.san} — look for a forcing move.`);}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500);}
function playSound(){if(!soundEnabled)return;try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=game.isCheck()?620:420;g.gain.setValueAtTime(.035,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.09);o.start();o.stop(c.currentTime+.09);}catch{}}

