ataset.ply)-1];$('#pgn-input').dataset.reviewFen=row.fen;btn.classList.toggle('selected');}));message.textContent=`Reviewed ${history.length} half-moves. All calculations stayed in this browser.`;}catch(err){message.textContent=`Could not complete review: ${err.message}`;message.classList.add('error');}finally{button.disabled=false;}},30);}
