input').addEventListener('dragover',e=>e.preventDefault());$('#pgn-input').addEventListener('drop',e=>{e.preventDefault();const f=e.dataTransfer.files?.[0];if(f)f.text().then(text=>$('#pgn-input').value=text);});}
